// Pin hinge leaf
// Prints flat: plate on the bed, knuckles along the +Y edge

$fn = 96;

// ---------- Plate ----------
plate_len   = 50;    // length along X
plate_wid   = 25;    // width along Y
plate_thk   = 2.5;   // thickness along Z

// ---------- Knuckles ----------
seg_count   = 5;                    // number of equal segments along the edge
seg_len     = plate_len / seg_count; // 10 mm per segment
knuckle_d   = 7;     // knuckle outer diameter
knuckle_y   = 12.5;  // knuckle axis Y position (plate +Y edge)
knuckle_z   = 3.5;   // knuckle axis Z position (bottom touches bed)

// ---------- Pin hole ----------
pin_d       = 3;     // pin hole diameter
cut_ext     = 0.5;   // overshoot of the hole past each knuckle face

// Segment indices (0-based) that carry knuckles: 1st, 3rd, 5th
knuckle_segs = [0, 2, 4];

// X start of a given segment
function seg_x0(i) = -plate_len/2 + i * seg_len;

module knuckle(i) {
    translate([seg_x0(i), knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = knuckle_d, h = seg_len);
}

module pin_cut(i) {
    translate([seg_x0(i) - cut_ext, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = seg_len + 2*cut_ext);
}

difference() {
    union() {
        // Flat plate centred on origin
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on segments 1, 3, 5
        for (i = knuckle_segs) knuckle(i);
    }

    // Pin hole through every knuckle
    for (i = knuckle_segs) pin_cut(i);
}

// Pin hinge leaf: flat plate with three knuckles along the +Y edge
// Print orientation: plate flat on the bed (z = 0), knuckles on top

$fn = 64;

// ---------- Plate ----------
plate_len   = 60;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

// ---------- Knuckles ----------
num_segments = 5;                          // segments along the hinge edge
seg_len      = plate_len / num_segments;   // 12 mm per segment
knuckle_d    = 6;                          // knuckle outer diameter (mm)
axis_y       = 12.5;                       // hinge axis Y position (mm)
axis_z       = 3;                          // hinge axis Z position (mm)

// ---------- Pin hole ----------
pin_d        = 2;    // pin hole diameter (mm)
cut_extra    = 1;    // how far the hole extends past the outer faces (mm)

difference() {
    union() {
        // Plate, centred on the origin in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the 1st, 3rd and 5th segments (indices 0, 2, 4)
        for (i = [0 : 2 : num_segments - 1])
            translate([-plate_len/2 + i * seg_len, axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole along the hinge axis through every knuckle
    translate([-plate_len/2 - cut_extra, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * cut_extra);
}

// Pin hinge leaf: flat plate with three knuckles along the +Y edge
// Units: mm. Print orientation: plate flat on the bed (z = 0).

// ---------------- Parameters ----------------
plate_len    = 50;    // plate length along X
plate_wid    = 30;    // plate width along Y
plate_thk    = 3;     // plate thickness along Z

num_segments = 5;     // number of equal segments along the hinge edge
seg_len      = plate_len / num_segments;  // 10 mm per segment

knuckle_d    = 6;     // knuckle outer diameter
knuckle_y    = 15;    // knuckle axis Y position (at the +Y edge)
knuckle_z    = 3;     // knuckle axis Z position (top of plate)

pin_d        = 2.5;   // pin hole diameter
cut_extra    = 0.5;   // extra length so cutters pass beyond faces

knuckle_segs = [0, 2, 4];  // 0-based indices of segments 1, 3 and 5

$fn = 96;             // smoothness for curved shapes

// ---------------- Model ----------------
difference() {
    union() {
        // Flat plate, centred on origin in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on segments 1, 3 and 5
        for (i = knuckle_segs)
            translate([-plate_len/2 + i*seg_len, knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole along the common knuckle axis, through every knuckle
    translate([-plate_len/2 - cut_extra, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*cut_extra);
}

// Pin hinge leaf: plate with two outer knuckles and a pin hole
// Print orientation: plate flat on bed (z = 0), knuckles along +Y edge

$fn = 96;

// ---------- Plate ----------
plate_len   = 45;    // X length of plate
plate_wid   = 30;    // Y width of plate
plate_thk   = 2.5;   // Z thickness of plate

// ---------- Knuckles ----------
n_segments  = 3;                       // number of equal segments along X
seg_len     = plate_len / n_segments;  // 15 mm per segment
knuckle_d   = 7;                       // knuckle outer diameter
axis_y      = 15;                      // hinge axis Y position (+Y edge)
axis_z      = 3.5;                     // hinge axis Z height
knuckle_idx = [0, 2];                  // segments carrying knuckles (1st and 3rd)

// ---------- Pin hole ----------
pin_d       = 2.5;   // pin hole diameter
cut_out     = 0.5;   // hole extension past outer knuckle ends
cut_in      = 0.01;  // hole extension past inner knuckle faces

// X start of segment i
function seg_x0(i) = -plate_len/2 + i * seg_len;

difference() {
    union() {
        // Flat plate centred on origin
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments
        for (i = knuckle_idx)
            translate([seg_x0(i), axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole through each knuckle along the hinge axis
    for (i = knuckle_idx) {
        ext_lo = (i == 0) ? cut_out : cut_in;
        ext_hi = (i == n_segments - 1) ? cut_out : cut_in;
        translate([seg_x0(i) - ext_lo, axis_y, axis_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = seg_len + ext_lo + ext_hi);
    }
}

