plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

n_segments  = 5;                       // number of equal segments along the hinge edge
seg_len     = plate_len / n_segments;  // 10 mm per segment

knuckle_d   = 6;     // knuckle outer diameter
axis_y      = 15;    // hinge axis Y position
axis_z      = 3;     // hinge axis Z height

pin_d       = 2.5;   // pin hole diameter
cut_ext     = 0.5;   // extension of cutters beyond faces

// ---------------- Model ----------------
difference() {
    union() {
        // Flat plate, centred on origin in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on segments 1, 3, 5 (index 0, 2, 4)
        for (i = [0 : 2 : n_segments - 1])
            translate([-plate_len/2 + i*seg_len, axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole along the hinge axis through every knuckle
