}

// Pin hinge leaf: flat plate with two outer knuckles and a pin hole
$fn = 96;

// Plate
plate_len   = 60;    // X length
plate_wid   = 20;    // Y width
plate_thk   = 3;     // Z thickness

// Knuckles
seg_count   = 3;                      // number of equal segments along X
seg_len     = plate_len / seg_count;  // 20 mm per segment
knuckle_d   = 7;                      // knuckle outer diameter
axis_y      = 10;                     // knuckle axis Y position (+Y edge)
axis_z      = 3.5;                    // knuckle axis Z height
knuckle_idx = [0, 2];                 // segments that carry knuckles (1st & 3rd)

// Pin hole
pin_d       = 2.5;   // pin hole diameter
eps         = 0.5;   // cutter overshoot past knuckle end faces

// X start of segment i
function seg_x0(i) = -plate_len/2 + i*seg_len;

difference() {
    union() {
        // Base plate centred on origin, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments
        for (i = knuckle_idx)
            translate([seg_x0(i), axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole through each knuckle along the common axis
    for (i = knuckle_idx)
        translate([seg_x0(i) - eps, axis_y, axis_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = seg_len + 2*eps);
}

// Star-shaped indexing wheel (6-pointed), flat plate printed lying on the bed

// ---------------- Parameters ----------------
n_points   = 6;    // number of star points
r_outer    = 30;   // radius to outer (tip) points [mm]
r_inner    = 15;   // radius to inner (valley) points [mm]
thickness  = 3;    // plate thickness [mm]
hole_d     = 6;    // centre through-hole diameter [mm]
eps        = 0.5;  // cutter overshoot past faces [mm]
$fn        = 96;   // curve resolution

// ---------------- Star outline ----------------
// Alternating outer/inner vertices, first outer point on +X axis
function star_pts(n, ro, ri) =
    [ for (i = [0 : 2*n - 1])
        let (a = i * 180 / n,
             r = (i % 2 == 0) ? ro : ri)
        [ r * cos(a), r * sin(a) ] ];

// ---------------- Model ----------------
difference() {
    linear_extrude(height = thickness)
        polygon(star_pts(n_points, r_outer, r_inner));

    // Centre hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2*eps);
}

// Star-shaped indexing wheel
// Units: mm

// ---- Parameters ----
num_points   = 5;      // number of star points
outer_r      = 35;     // radius of outer (tip) points
inner_r      = 17.5;   // radius of inner (valley) points
plate_thick  = 4;      // plate thickness
hole_d       = 6;      // centre through-hole diameter
cut_extra    = 0.5;    // overshoot of cutting shapes past faces
$fn          = 96;     // curve resolution

// ---- Star outline points (first outer point on +X) ----
step = 360 / (2 * num_points);
star_pts = [
    for (i = [0 : 2 * num_points - 1])
        let (r = (i % 2 == 0) ? outer_r : inner_r,
             a = i * step)
        [r * cos(a), r * sin(a)]
];

// ---- Part ----
difference() {
    // Star plate resting on the bed
    linear_extrude(height = plate_thick)
        polygon(points = star_pts);

    // Centre hole, extended past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_thick + 2 * cut_extra, $fn = 96);
}

