// Tapered riser block for raising a beaker
// Solid square frustum with a square pocket in the top face

// ---- Dimensions (mm) ----
base_size    = 80;   // bottom square side length (z = 0)
top_size     = 50;   // top square side length (z = height)
height       = 30;   // overall height of the frustum
pocket_size  = 40;   // square pocket side length
pocket_depth = 5;    // pocket depth from top face
eps          = 0.5;  // overshoot for clean boolean cuts

// ---- Model ----
difference() {
    // Square frustum: linear_extrude with scale gives flat sloping sides
    linear_extrude(height = height, scale = top_size / base_size)
        square([base_size, base_size], center = true);

    // Centred square pocket cut into the top face
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}

