// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on the origin

// ---------------- Parameters ----------------
thickness      = 5;    // overall wheel thickness (Z)
rim_od         = 80;   // rim outer diameter
rim_width      = 5;    // rim radial width
hub_d          = 16;   // hub diameter
axle_d         = 5;    // axle hole diameter
spoke_count    = 8;    // number of spokes
spoke_width    = 5;    // spoke width
spoke_overlap  = 1;    // how far spokes extend into hub/rim for solid union
eps            = 0.5;  // cut overshoot past faces

$fn = 128;

// ---------------- Derived ----------------
rim_id       = rim_od - 2 * rim_width;      // rim inner diameter (70)
spoke_start  = hub_d / 2 - spoke_overlap;   // spoke inner end radius
spoke_end    = rim_id / 2 + spoke_overlap;  // spoke outer end radius
spoke_len    = spoke_end - spoke_start;

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes, first along +X
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_start, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps, $fn = 64);
}

