rim_width      = 6;     // radial width of rim ring
hub_d          = 14;    // hub outer diameter
axle_d         = 6;     // axle hole diameter
spoke_count    = 6;     // number of spokes
spoke_w        = 5;     // spoke width
spoke_start_a  = 0;     // first spoke angle (along +X)

