module hub() {
    cylinder(h = wheel_thk, r = hub_r);
}

module spokes() {
    spoke_len = (rim_ir + overlap) - (hub_r - overlap);
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, spoke_start_a + i * 360 / spoke_count])
            translate([hub_r - overlap, -spoke_w/2, 0])
                cube([spoke_len, spoke_w, wheel_thk]);
}

