// ---- Frustum via polyhedron ----
module frustum(b, t, h) {
    hb = b / 2;
    ht = t / 2;
    polyhedron(
        points = [
            [-hb, -hb, 0], [ hb, -hb, 0], [ hb,  hb, 0], [-hb,  hb, 0],  // bottom 0-3
            [-ht, -ht, h], [ ht, -ht, h], [ ht,  ht, h], [-ht,  ht, h]   // top 4-7
        ],
        faces = [
            [0, 1, 2, 3],   // bottom
            [4, 7, 6, 5],   // top
            [0, 4, 5, 1],   // front (-Y)
            [1, 5, 6, 2],   // right (+X)
            [2, 6, 7, 3],   // back (+Y)
            [3, 7, 4, 0]    // left (-X)
        ]
    );
}

// ---- Part ----
difference() {
    frustum(base_size, top_size, block_height);

    // Square pocket cut down from the top face
    translate([-pocket_size / 2, -pocket_size / 2, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}

