knuckle_d   = 7;                       // knuckle outer diameter (mm)
axis_y      = 12.5;                    // hinge axis Y position (mm)
axis_z      = 3.5;                     // hinge axis Z position (mm)

// ---------- Pin hole ----------
pin_d       = 2;     // pin hole diameter (mm)
eps         = 0.5;   // overshoot for clean boolean cuts (mm)

// X start of segment i (0-based)
function seg_x0(i) = -plate_len/2 + i*seg_len;

difference() {
    union() {
        // Flat plate centred on origin
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (indices 0, 2, 4)
        for (i = [0 : 2 : n_segments-1])
            translate([seg_x0(i), axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole along the hinge axis, through every knuckle
    translate([-plate_len/2 - eps, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}

