step = 360 / (2 * n_points);   // angle between successive vertices

// Star outline: alternates outer and inner points, first outer point on +X
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (r = (i % 2 == 0) ? r_outer : r_inner,
             a = i * step)
        [r * cos(a), r * sin(a)]
];

