    linear_extrude(height = plate_t)
        polygon(points = star_pts);

    // Centre through-hole, extending past top and bottom faces
    translate([0, 0, -cut_overlap])
        cylinder(d = hole_d, h = plate_t + 2 * cut_overlap, $fn = 96);
}

